import json, html, pathlib
root=pathlib.Path(__file__).resolve().parent
records=json.loads((root/"specifications.json").read_text())
e=html.escape
head=lambda title: f'''<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — formalize.now</title><link rel="stylesheet" href="/styles/site.css"><link rel="stylesheet" href="/styles/feed.css"><script src="/feed-theme.js"></script></head>'''
nav='''<a class="skip" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><nav class="nav" aria-label="Main navigation"><a href="/feed.html">Specifications</a><a href="/rlt/">RLT</a><a href="https://rlt-fro.now/">RLT-FRO</a><button type="button" class="theme-toggle" id="theme-toggle">◐ Theme</button></nav><a class="brand" href="/">formalize<span>.now</span></a></div></header>'''
foot='''<footer class="footer"><div class="container footer-inner"><span>Leading specifications verify trailing generalizations.</span><a href="https://rlt-fro.now/">RLT-FRO</a></div></footer>'''
mathjax='''<script>window.MathJax={tex:{inlineMath:[['\\\\(','\\\\)']]}};</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3.2.2/es5/tex-chtml.js"></script>'''
cards=[]
for r in records:
 cards.append(f'''<article class="card feed-card" data-category="{e(r['category'],quote=True)}"><span class="tag">{e(r['category'])} · {e(r['id'])}</span><h3><a href="/{e(r['page'])}">{e(r['title'])}</a></h3><p>{e(r['summary'])}</p><p class="small feed-status">{e(r['status'])}</p><a href="/{e(r['page'])}">Read specification →</a></article>''')
 p=root/r['page'];p.mkdir(parents=True,exist_ok=True)
 formula=f'<div class="code formula">\\[{e(r["math"])}\\]</div>' if r['math'] else ''
 links=''.join(f'<li><a href="{e(x["url"],quote=True)}">{e(x["label"])}</a></li>' for x in r['links'])
 (p/'index.html').write_text(head(r['title']).replace('</head>',mathjax+'</head>')+f'''<body>{nav}<main id="main" class="container"><section class="hero feed-hero"><span class="eyebrow">{e(r['category'])} · {e(r['id'])}</span><h1>{e(r['title'])}</h1><p class="subtitle">{e(r['summary'])}</p><p class="small">{e(r['status'])}</p><div class="actions"><a class="btn primary" href="{e(r['source'],quote=True)}">Full research record →</a><a class="btn" href="/feed.html">All specifications</a></div></section><section class="section"><h2>Reading point and evidence</h2><p class="lead">{e(r['detail'])}</p>{formula}<div class="note"><strong>Scope.</strong> {e(r['scope'])}</div></section><section class="section"><h2>Sources and research</h2><ul><li><a href="{e(r['source'],quote=True)}">Original RLT-FRO research record, including its evidence and source links</a></li>{links}</ul><p class="small">This page is a concise entry point to the existing research record, not a new independent verification.</p></section></main>{foot}</body></html>''')
options=''.join(f'<option>{e(x)}</option>' for x in sorted({r['category'] for r in records}))
(root/'feed.html').write_text(head('Specifications')+f'''<body>{nav}<main id="main" class="container"><section class="hero feed-hero"><span class="eyebrow">Mathematics · computation · science</span><h1>Specifications.</h1><p class="subtitle">Leading specifications verify trailing generalizations.</p><p class="lead">Reading points, formal relationships and evidence for independent examination.</p></section><section class="section feed-list"><div class="feed-controls" id="feed-controls" hidden><label>Search <input id="feed-search" type="search" placeholder="Title, subject or specification"></label><label>Subject <select id="feed-category"><option value="">All subjects</option>{options}</select></label><p class="small" id="feed-count" aria-live="polite"></p></div><div class="grid" id="feed-grid">{''.join(cards)}</div><p id="feed-empty" hidden>No matching specifications.</p></section></main>{foot}<script src="/feed-filter.js" defer></script></body></html>''')
(root/'styles').mkdir(exist_ok=True)
(root/'styles/feed.css').write_text('''.feed-hero{padding:48px 0 38px}.feed-hero h1{font-size:clamp(2.4rem,5vw,4.2rem)}.feed-list{padding:32px 0 54px}.feed-controls:not([hidden]){display:flex;flex-wrap:wrap;align-items:end;gap:16px;margin-bottom:24px}.feed-controls label{display:grid;gap:5px;color:var(--muted);font-size:.88rem}.feed-controls input,.feed-controls select{font:inherit;color:var(--text);background:var(--paper);border:1px solid var(--line);border-radius:8px;padding:9px 12px;max-width:100%}.feed-controls input{width:min(310px,75vw)}.feed-card{display:flex;flex-direction:column;align-items:flex-start}.feed-card h3 a{color:var(--text);text-decoration:none}.feed-card h3 a:hover{color:var(--accent);text-decoration:underline}.feed-card .feed-status{margin-top:auto}.feed-card[hidden],#feed-empty[hidden]{display:none}.formula{overflow-x:auto}.feed-controls :focus-visible{outline:3px solid var(--accent);outline-offset:3px}''')
(root/'feed-theme.js').write_text('''(()=>{const root=document.documentElement;function saved(){try{return localStorage.getItem('rlt-theme')}catch{return null}}root.dataset.theme=saved()==='dark'?'dark':'light';document.addEventListener('DOMContentLoaded',()=>{const b=document.getElementById('theme-toggle');if(!b)return;function set(t){root.dataset.theme=t;b.setAttribute('aria-pressed',String(t==='dark'));b.textContent=t==='dark'?'☼ Light':'◐ Dark'}set(root.dataset.theme);b.addEventListener('click',()=>{const t=root.dataset.theme==='dark'?'light':'dark';set(t);try{localStorage.setItem('rlt-theme',t)}catch{}})})})();''')
(root/'feed-filter.js').write_text('''(()=>{const q=document.getElementById('feed-search'),c=document.getElementById('feed-category'),cards=[...document.querySelectorAll('.feed-card')];function filter(){let n=0;for(const card of cards){const match=(!c.value||card.dataset.category===c.value)&&card.textContent.toLowerCase().includes(q.value.trim().toLowerCase());card.hidden=!match;if(match)n++}document.getElementById('feed-count').textContent=`${n} of ${cards.length} specifications`;document.getElementById('feed-empty').hidden=n!==0}document.getElementById('feed-controls').hidden=false;q.addEventListener('input',filter);c.addEventListener('change',filter);filter()})();''')
(root/'FEED-README.md').write_text('''# Specification feed\n\nExtract into the root of thinkthoughts/formalize. Existing index.html and styles/site.css remain unchanged. Visit /feed.html. All nine cards have local detail pages under /specifications/ and link to the original full research records. The pages use the existing site.css and the same rlt-theme localStorage key. MathJax is loaded only on detail pages (external pinned CDN).\n\nThe HTML is static for accessibility and no-JS reading. specifications.json is a machine-readable inventory of the initial records; edits to it do not automatically update HTML. To regenerate the static cards and detail pages, run python3 build-specifications.py from the repository root. Custom long-form pages can be edited separately; the generator overwrites the generated detail pages, so preserve custom edits before running it. No date-based ordering.\n\nStatus is a summary of the linked research pages, not an independent audit. Keep the full records at their current URLs for now.\n''')
